// true loft of the band profile along print z (no hull: the profile is
// concave). Full thickness at z=0 (flat bed face), far edge rounded off.
module saddle() {
    zt = [[0, 6], [37.5, 6], [39, 5.6], [40.5, 4.6], [42, 1.2]];
    n = len(band_points(6));
    pts = [for (s = zt) for (p = band_points(s[1])) [p[0], p[1], s[0]]];
    side = [for (i = [0 : len(zt) - 2]) for (j = [0 : n - 1])
        [i*n + j, i*n + (j+1)%n, (i+1)*n + (j+1)%n, (i+1)*n + j]];
    cap0 = [for (j = [0 : n - 1]) j];
    cap1 = [for (j = [n-1 : -1 : 0]) (len(zt)-1)*n + j];
    polyhedron(points = pts, faces = concat([cap0], side, [cap1]));
}

arguments.new:
// saddle along print z: full-thickness prism to z=37.5 (flat bed face at
// z=0), then thin stepped slices easing the far edge down (rounded edge).
module saddle() {
    linear_extrude(37.5) polygon(points = band_points(6));
    for (i = [0 : 5]) {
        zc = 37.5 + (i + 0.5) * 0.75;
        t = 1.2 + 4.8 * cos((zc - 37.5) / 4.5 * 90);
        translate([0, 0, 37.5 + i * 0.75]) linear_extrude(0.77)
            polygon(points = band_points(t));
    }
}
